import csv, json
from pathlib import Path
root=Path(__file__).parent
with (root/'booking_sessions.csv').open() as f:
    rows=list(csv.DictReader(f))
compact=[[r['session_date'],r['variant'],r['device'],r['channel'],r['route_type'],int(r['flight_selected']),int(r['checkout_started']),int(r['booking_completed']),float(r['booking_revenue'])] for r in rows]
template=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Airline Booking Experiment | Ella Simeon</title><style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#14213d;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1250px;margin:auto;padding:32px 24px 70px}header{background:#081f43;color:white;padding:35px 0 38px}header .wrap{padding-top:0;padding-bottom:0}.eyebrow{color:#72d5f5;font-weight:800;letter-spacing:.15em;text-transform:uppercase;font-size:12px}h1{font-size:clamp(30px,4vw,50px);margin:12px 0 8px;letter-spacing:-.045em}header p{color:#c7d8eb;max-width:720px;line-height:1.5}header .tag{display:inline-block;background:#254469;color:#dceaf9;border-radius:20px;padding:7px 12px;font-size:12px;font-weight:700}main h2{font-size:22px;letter-spacing:-.03em;margin:36px 0 16px}.filters{background:white;border:1px solid #dce5ef;border-radius:18px;padding:20px;display:flex;gap:16px;flex-wrap:wrap;align-items:end;margin-top:-4px;box-shadow:0 8px 28px #0c29530b}.filters label{display:grid;gap:7px;color:#53657b;font-size:12px;font-weight:750;text-transform:uppercase;letter-spacing:.08em}.filters select{min-width:160px;border:1px solid #cbd8e6;border-radius:9px;background:white;color:#14213d;padding:10px;font-size:14px}.filters button{padding:11px 16px;border:1px solid #cbd8e6;background:white;color:#14365e;border-radius:9px;font-weight:700;cursor:pointer}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-top:20px}.card,.panel{background:#fff;border:1px solid #dce5ef;border-radius:18px;box-shadow:0 8px 28px #0c29530b}.card{padding:21px}.label{color:#60718a;font-size:12px;text-transform:uppercase;font-weight:800;letter-spacing:.08em}.value{font-size:30px;letter-spacing:-.04em;font-weight:800;margin:12px 0 4px}.sub{font-size:13px;color:#64748b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{padding:23px;min-width:0}.panel h3{margin:0 0 20px;font-size:18px}.legend{display:flex;gap:18px;font-size:13px;color:#586a7e;margin-bottom:18px}.dot{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:6px}.row{display:grid;grid-template-columns:112px 1fr 70px;align-items:center;gap:12px;margin:15px 0;font-size:13px}.track{height:24px;background:#edf3f8;border-radius:5px;overflow:hidden}.fill{height:100%;border-radius:5px}.control{background:#83a4c9}.treatment{background:#16a8c9}.row small{color:#586a7e}.callout{padding:18px 20px;background:#eef6ff;border-left:4px solid #2086c3;border-radius:9px;line-height:1.55}.warning{background:#fff7e9;border-color:#edaa3c}.method{line-height:1.7;color:#465771;font-size:14px}.foot{font-size:12px;color:#61728a;margin-top:26px}.segment-table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;border-bottom:1px solid #e7eef5;padding:12px 8px}th{font-size:11px;text-transform:uppercase;color:#60718a;letter-spacing:.05em}td:last-child,th:last-child{text-align:right}.positive{color:#087d73}.negative{color:#a05336}@media(max-width:900px){.kpis{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:530px){.kpis{grid-template-columns:1fr}.row{grid-template-columns:85px 1fr 55px}.filters select{min-width:130px}}
</style></head><body><header><div class="wrap"><div class="eyebrow">Ella Simeon · Portfolio case study</div><h1>Flight Search A/B Test</h1><p>Would a clearer flight selection experience increase completed bookings? Explore the funnel, segments, and statistical result of a simulated airline experiment.</p><span class="tag">SIMULATED DATA · NOT A JETBLUE EXPERIMENT</span></div></header><main class="wrap"><div class="filters"><label>Device<select id="device"><option>All</option><option>Mobile</option><option>Desktop</option><option>Tablet</option></select></label><label>Channel<select id="channel"><option>All</option><option>Direct</option><option>Organic Search</option><option>Paid Search</option><option>Email</option></select></label><label>Route type<select id="route"><option>All</option><option>Domestic</option><option>Caribbean</option><option>International</option></select></label><button id="reset">Reset filters</button></div><div class="kpis"><div class="card"><div class="label">Total sessions</div><div class="value" id="sessions"></div><div class="sub">Equal random assignment by design</div></div><div class="card"><div class="label">Control conversion</div><div class="value" id="controlRate"></div><div class="sub">Bookings ÷ sessions</div></div><div class="card"><div class="label">Treatment conversion</div><div class="value" id="treatmentRate"></div><div class="sub">Bookings ÷ sessions</div></div><div class="card"><div class="label">Relative lift</div><div class="value" id="lift"></div><div class="sub" id="absolute"></div></div></div><h2>Where customers drop off</h2><div class="grid"><div class="panel"><h3>Conversion funnel</h3><div class="legend"><span><i class="dot control"></i>Control</span><span><i class="dot treatment"></i>Treatment</span></div><div id="funnel"></div><div class="foot">Bars show the share of assigned sessions reaching each step.</div></div><div class="panel"><h3>Experiment decision</h3><div class="callout" id="decision"></div><p class="method" id="stats"></p><p class="method">The primary measure is booking conversion per assigned session. A two sided pooled z test compares the two proportions; the confidence interval uses the unpooled standard error. Segment filters are exploratory and are not separate pre registered tests.</p></div></div><h2>Device breakdown</h2><div class="panel"><table class="segment-table"><thead><tr><th>Device</th><th>Control sessions</th><th>Control rate</th><th>Treatment sessions</th><th>Treatment rate</th><th>Difference</th></tr></thead><tbody id="segments"></tbody></table></div><p class="foot">Synthetic portfolio exercise generated with a fixed random seed. No JetBlue transactions, customer records, or business results were used. The result does not justify a real launch decision.</p></main><script>const data=__DATA__;
const $=id=>document.getElementById(id);const fmt=n=>n.toLocaleString();const pct=n=>n==null?'—':(100*n).toFixed(2)+'%';
function summarize(rows){const n=rows.length;return {n,selected:rows.reduce((x,r)=>x+r[5],0),checkout:rows.reduce((x,r)=>x+r[6],0),bookings:rows.reduce((x,r)=>x+r[7],0),revenue:rows.reduce((x,r)=>x+r[8],0)}}
function infer(c,t){if(!c.n||!t.n)return null;const p0=c.bookings/c.n,p1=t.bookings/t.n,pooled=(c.bookings+t.bookings)/(c.n+t.n),se=Math.sqrt(pooled*(1-pooled)*(1/c.n+1/t.n)),z=(p1-p0)/se;const erf=x=>{const s=x<0?-1:1;x=Math.abs(x);const v=1/(1+.3275911*x);return s*(1-(((((1.061405429*v-1.453152027)*v)+1.421413741)*v-.284496736)*v+.254829592)*v*Math.exp(-x*x))};const p=1-erf(Math.abs(z)/Math.SQRT2);const seCI=Math.sqrt(p0*(1-p0)/c.n+p1*(1-p1)/t.n);return {p0,p1,d:p1-p0,rel:p1/p0-1,p,lo:p1-p0-1.96*seCI,hi:p1-p0+1.96*seCI}}
function render(){const selected=data.filter(r=>($('device').value==='All'||r[2]===$('device').value)&&($('channel').value==='All'||r[3]===$('channel').value)&&($('route').value==='All'||r[4]===$('route').value));const c=summarize(selected.filter(r=>r[1]==='Control')),t=summarize(selected.filter(r=>r[1]==='Treatment')),s=infer(c,t);$('sessions').textContent=fmt(c.n+t.n);$('controlRate').textContent=s?pct(s.p0):'—';$('treatmentRate').textContent=s?pct(s.p1):'—';$('lift').textContent=s?(s.rel>=0?'+':'')+pct(s.rel):'—';$('absolute').textContent=s?`${s.d>=0?'+':''}${(100*s.d).toFixed(2)} percentage points`:'Insufficient sessions';const stages=[['Sessions','n'],['Flight selected','selected'],['Checkout started','checkout'],['Booked','bookings']];$('funnel').innerHTML=stages.map(([label,key])=>`<div class="row"><strong>${label}</strong><div><div class="track"><div class="fill control" style="width:${c.n?100*c[key]/c.n:0}%"></div></div><div class="track" style="margin-top:4px"><div class="fill treatment" style="width:${t.n?100*t[key]/t.n:0}%"></div></div></div><small>${fmt(c[key])}<br>${fmt(t[key])}</small></div>`).join('');if(s){$('decision').className='callout '+(s.p>=.05?'warning':'');$('decision').innerHTML=s.p<.05?'<strong>Statistically detectable difference at the 5% level.</strong> Examine commercial impact and guardrail metrics before any rollout.':'<strong>Evidence is inconclusive at the 5% level.</strong> Treatment is higher in this simulated sample, but the interval includes no improvement. Do not claim the redesign increased bookings.';$('stats').innerHTML=`Observed difference: <strong>${(100*s.d).toFixed(2)} percentage points</strong><br>95% confidence interval: <strong>${(100*s.lo).toFixed(2)} to ${(100*s.hi).toFixed(2)} points</strong><br>Two sided p value: <strong>${s.p.toFixed(3)}</strong>`}else{$('decision').textContent='No observations for this selection.';$('stats').textContent=''}$('segments').innerHTML=['Mobile','Desktop','Tablet'].map(d=>{const a=summarize(selected.filter(r=>r[1]==='Control'&&r[2]===d)),b=summarize(selected.filter(r=>r[1]==='Treatment'&&r[2]===d));const diff=a.n&&b.n?b.bookings/b.n-a.bookings/a.n:null;return `<tr><td>${d}</td><td>${fmt(a.n)}</td><td>${pct(a.n?a.bookings/a.n:null)}</td><td>${fmt(b.n)}</td><td>${pct(b.n?b.bookings/b.n:null)}</td><td class="${diff>=0?'positive':'negative'}">${diff==null?'—':(diff>=0?'+':'')+(100*diff).toFixed(2)+' pp'}</td></tr>`}).join('')}
for(const id of ['device','channel','route'])$(id).addEventListener('change',render);$('reset').addEventListener('click',()=>{for(const id of ['device','channel','route'])$(id).value='All';render()});render();</script></body></html>'''
(root/'dashboard.html').write_text(template.replace('__DATA__',json.dumps(compact,separators=(',',':'))))
